<template>
  <div
    ref="outerContainerRef"
    class="flex flex-col items-center gap-3 sm:flex-row sm:justify-between sm:flex-wrap sm:gap-4"
  >
    <p v-if="label" class="text-sm leading-6 font-medium text-accent-muted">
      Showing {{ displayedItemsRange }} of {{ total }} {{ label }}
    </p>

    <div
      v-if="total > size"
      ref="paginationContainerRef"
      class="w-full sm:flex-1 flex justify-center"
      :class="[isWrapped ? 'sm:justify-start' : 'sm:justify-end', { invisible: !isMeasured }]"
    >
      <Pagination
        :page="page"
        :items-per-page="size"
        :total="total"
        :sibling-count="siblingCount"
        show-edges
        @update:page="(value: number) => emit('update:page', value)"
      >
        <PaginationList v-slot="{ items }" class="flex items-center gap-1">
          <component
            :is="navigate && page > 1 ? NuxtLink : 'div'"
            :to="navigate && page > 1 ? routeAtPage(page - 1) : undefined"
          >
            <PaginationPrev class="w-8 sm:w-10 h-9 sm:h-10" />
          </component>
          <template v-for="(item, index) in items" :key="index">
            <PaginationListItem v-if="item.type === 'page'" :value="item.value" as-child>
              <Button
                :as="navigate ? NuxtLink : 'button'"
                :to="navigate ? routeAtPage(item.value) : undefined"
                class="min-w-8 sm:min-w-10 h-9 sm:h-10 p-1"
                variant="outline"
                :class="{ 'text-blue-500 border-blue-500 hover:text-blue-500': item.value === page }"
              >
                {{ item.value }}
              </Button>
            </PaginationListItem>
            <PaginationEllipsis v-else :key="item.type" :index="index" />
          </template>
          <component
            :is="navigate && page < totalPages ? NuxtLink : 'div'"
            :to="navigate && page < totalPages ? routeAtPage(page + 1) : undefined"
          >
            <PaginationNext class="w-8 sm:w-10 h-9 sm:h-10" />
          </component>
        </PaginationList>
      </Pagination>
    </div>
  </div>
</template>

<script setup lang="ts">
import { useElementSize } from '@vueuse/core';
import type { RouteLocationRaw } from 'vue-router';

interface Props {
  page: number;
  size: number;
  total: number;
  label?: string;
  propertyName?: string;
  // When true, page changes are emitted via `update:page` instead of navigating the URL. Use inside
  // modals or on pages with an unsaved-changes route guard, where URL query changes are undesirable.
  controlled?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  label: 'items',
  propertyName: 'page',
  controlled: false,
});

const emit = defineEmits<{ 'update:page': [page: number] }>();

// Resolved component so `<component :is>` / `:as` render the real NuxtLink instead of a literal <NuxtLink> tag.
const NuxtLink = resolveComponent('NuxtLink');

// Route mode links each control to a URL query; controlled mode keeps plain buttons and emits `update:page`.
const navigate = computed<boolean>(() => !props.controlled);

const totalPages = computed<number>(() => {
  return Math.ceil(props.total / props.size);
});

const displayedItemsRange = computed<string>(() => {
  return props.page * props.size - (props.size - 1) + '-' + Math.min(props.page * props.size, props.total);
});

const outerContainerRef = ref<HTMLElement | null>(null);
const paginationContainerRef = ref<HTMLElement | null>(null);
const { width: outerWidth } = useElementSize(outerContainerRef);
const { width: containerWidth } = useElementSize(paginationContainerRef);

// Both widths come from ResizeObserver and stay 0 until the first observation.
// Hide the pager until then so the first paint already has the correct
// alignment and sibling count, instead of flipping on the next tick.
const isMeasured = computed<boolean>(() => outerWidth.value > 0 && containerWidth.value > 0);

// When the pager wrapper's width matches the outer container's width, the
// flex row has wrapped and the pager sits on its own line.
const isWrapped = computed<boolean>(() => {
  return outerWidth.value > 0 && containerWidth.value >= outerWidth.value - 2;
});

// Pager buttons: w-8 (32px) on mobile, w-10 (40px) on sm+, gap-1 between items.
const SM_BUTTON = 40;
const MOBILE_BUTTON = 32;
const GAP = 4;
const ELLIPSIS_WIDTH = 24;
// Asymmetric on purpose: fixed slots (prev/next + first/last + current + 2
// ellipses) are sized to the mobile button so narrow screens get more
// siblings, while per-sibling cost uses the sm+ button so we under-show on
// mobile rather than overflow on sm+ in constrained containers.
const FIXED_COST = 5 * (MOBILE_BUTTON + GAP) + 2 * ELLIPSIS_WIDTH;
const ITEM_WIDTH = SM_BUTTON + GAP;
const MAX_SIBLINGS = 2;

const siblingCount = computed<number>(() => {
  if (!containerWidth.value) return 0;
  const available = containerWidth.value - FIXED_COST;
  if (available <= 0) return 0;
  return Math.min(MAX_SIBLINGS, Math.floor(available / (ITEM_WIDTH * 2)));
});

function routeAtPage(page: number): RouteLocationRaw {
  const route = useRoute();
  return {
    query: {
      ...route.query,
      [props.propertyName]: page.toString(),
    },
  };
}
</script>

<style scoped lang="scss"></style>
